using WpfColorConv     = System.Windows.Media.ColorConverter;

namespace SMDWin.Views
{
    public class EmptyStringToCollapsedConverter : System.Windows.Data.IValueConverter
    {
        public object Convert(object? value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
            => string.IsNullOrWhiteSpace(value as string) ? Visibility.Collapsed : Visibility.Visible;

        public object ConvertBack(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
            => throw new NotImplementedException();
    }

    public class ForegroundToPillBgConverter : System.Windows.Data.IValueConverter
    {
        public object Convert(object? value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
            => value is System.Windows.Media.SolidColorBrush scb
                ? new System.Windows.Media.SolidColorBrush(scb.Color) { Opacity = 0.15 }
                : System.Windows.Media.Brushes.Transparent;

        public object ConvertBack(object value, Type targetType, object parameter, System.Globalization.CultureInfo culture)
            => throw new NotImplementedException();
    }
}
